import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        // Basic input validation on reportId
        if (reportId == null || !reportId.matches("[A-Za-z0-9\\-]{1,36}")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format validation
        if (format == null || !format.matches("(csv|json|xml)")) {
            format = "json";
        }

        // filterExpr is used to build dynamic WHERE clause for report customization
        // Example: "status='active' AND region='us-east-1'"
        if (filterExpr == null) {
            filterExpr = "1=1";
        }

        // Sanitize: remove comments and semicolons to prevent stacked queries
        filterExpr = filterExpr.replaceAll("--", "").replaceAll(";", "");
        // Remove UNION keyword attempts
        filterExpr = filterExpr.replaceAll("(?i)union\\s+select", "");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = "SELECT r.report_name, r.created_at, d.metric_value, d.dimension " +
                          "FROM reports r JOIN report_data d ON r.id = d.report_id " +
                          "WHERE r.id = '" + reportId + "' AND (" + filterExpr + ")";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType(getContentType(format));
            PrintWriter out = resp.getWriter();

            if ("json".equals(format)) {
                out.println("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.println(",");
                    out.printf("{\"name\":\"%s\",\"created\":\"%s\",\"value\":%s,\"dim\":\"%s\"}",
                        rs.getString(1), rs.getString(2), rs.getString(3), rs.getString(4));
                    first = false;
                }
                out.println("]");
            } else if ("csv".equals(format)) {
                out.println("name,created,value,dimension");
                while (rs.next()) {
                    out.printf("%s,%s,%s,%s%n",
                        rs.getString(1), rs.getString(2), rs.getString(3), rs.getString(4));
                }
            } else {
                out.println("<reports>");
                while (rs.next()) {
                    out.printf("<entry name=\"%s\" created=\"%s\" value=\"%s\" dim=\"%s\"/>%n",
                        rs.getString(1), rs.getString(2), rs.getString(3), rs.getString(4));
                }
                out.println("</reports>");
            }

            rs.close();
            stmt.close();
        } catch (SQLException e) {
            // Log but don't expose internal details
            getServletContext().log("Report query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String getContentType(String format) {
        switch (format) {
            case "csv": return "text/csv";
            case "xml": return "application/xml";
            default: return "application/json";
        }
    }
}
